const Q=[[2,0],[0,2],[1,1]];
const K=[[1,0],[1,1],[0,1]];
const V=[[1,0],[0,2],[3,1]];
const DK=2;
function vec(a){return '['+a[0]+', '+a[1]+']';}
export function evaluate({ inputs }){
  const i=parseInt(inputs.query,10)-1;
  const masked=inputs.mask==='on';
  const f=(v)=>sdk.format(v,2);
  const s=[],dots=[],allowed=[];
  for(let j=0;j<3;j++){
    dots[j]=Q[i][0]*K[j][0]+Q[i][1]*K[j][1];
    s[j]=dots[j]/Math.sqrt(DK);
    allowed[j]=!(masked&&j>i);
  }
  let m=-Infinity;
  for(let j=0;j<3;j++){if(allowed[j]&&s[j]>m)m=s[j];}
  const e=[];let Z=0;
  for(let j=0;j<3;j++){e[j]=allowed[j]?Math.exp(s[j]-m):0;Z+=e[j];}
  const w=e.map(x=>x/Z);
  const o=[0,0];
  for(let j=0;j<3;j++){o[0]+=w[j]*V[j][0];o[1]+=w[j]*V[j][1];}
  const objs=[];
  objs.push(sdk.text('title',24,30,'One attention row for query token t'+(i+1)+' (causal mask '+(masked?'on':'off')+')'));
  objs.push(sdk.text('tablecap',24,70,'Synthetic vectors, key size d_k = 2'));
  const cols=[40,110,200,290];
  const rowY=[105,140,175,210];
  objs.push(sdk.box('qrow',28,rowY[i+1]-15,330,30,{role:'input',opacity:0.3}));
  const hdr=['token','query q','key k','value v'];
  for(let c=0;c<4;c++)objs.push(sdk.text('h'+c,cols[c],rowY[0],hdr[c]));
  for(let j=0;j<3;j++){
    const y=rowY[j+1];
    const r=(j===i)?'input':'neutral';
    objs.push(sdk.text('tok'+j,cols[0],y,'t'+(j+1),{role:r}));
    objs.push(sdk.text('q'+j,cols[1],y,vec(Q[j]),{role:r}));
    objs.push(sdk.text('k'+j,cols[2],y,vec(K[j])));
    objs.push(sdk.text('v'+j,cols[3],y,vec(V[j])));
  }
  objs.push(sdk.text('hl1',24,255,'Highlighted row: the chosen query q_'+(i+1)+' = '+vec(Q[i])+'.'));
  objs.push(sdk.text('hl2',24,285,'It is compared with every key k_j.'));
  objs.push(sdk.text('hl3',24,315,masked?'Mask on: keys after t'+(i+1)+' are hidden.':'Mask off: every key is visible.',{role:masked?'warning':'neutral'}));
  objs.push(sdk.math('fs',440,75,'s_j = \\frac{q_i \\cdot k_j}{\\sqrt{d_k}}'));
  objs.push(sdk.text('colh1',440,115,'Scaled score for each key'));
  objs.push(sdk.text('colh2',700,115,'Softmax weight'));
  for(let j=0;j<3;j++){
    const y=155+j*50;
    let t;
    if(allowed[j]) t='k_'+(j+1)+': q·k = '+dots[j]+', s = '+dots[j]+'/√2 = '+f(s[j]);
    else t='k_'+(j+1)+': later token, masked, s = −∞';
    objs.push(sdk.text('sc'+j,440,y,t,{role:allowed[j]?'neutral':'warning'}));
    objs.push(sdk.box('bar'+j,700,y-10,Math.max(2,170*w[j]),20,{role:'output'}));
    objs.push(sdk.text('wt'+j,885,y,'w = '+f(w[j]),{role:allowed[j]?'output':'warning'}));
  }
  objs.push(sdk.math('fw',440,320,'w_j = \\frac{e^{s_j}}{\\sum_{l} e^{s_l}}'));
  objs.push(sdk.text('wsum',600,320,'sum over visible keys; weights add to '+f(w[0]+w[1]+w[2])));
  objs.push(sdk.math('fo',24,400,'o_i = \\sum_j w_j\\, v_j'));
  objs.push(sdk.text('terms',24,445,'o = '+f(w[0])+'·[1, 0] + '+f(w[1])+'·[0, 2] + '+f(w[2])+'·[3, 1]'));
  objs.push(sdk.text('out',24,480,'o_'+(i+1)+' = ['+f(o[0])+', '+f(o[1])+']',{role:'output'}));
  objs.push(sdk.text('note',24,520,'The better a key matches the query, the larger its weight and the more of its value enters o.'));
  return { frame: sdk.frame(objs,{width:960,height:540,readouts:[{id:'w1',value:w[0]},{id:'w2',value:w[1]},{id:'w3',value:w[2]},{id:'o1',value:o[0]},{id:'o2',value:o[1]}]}), quantities:{s1:allowed[0]?s[0]:-1e9,s2:allowed[1]?s[1]:-1e9,s3:allowed[2]?s[2]:-1e9,w1:w[0],w2:w[1],w3:w[2],o1:o[0],o2:o[1]} };
}

